// 自动生成：demo 封面 PNG 数据。
// 通过 base64 内联以避免 SPM 资源 bundle 在 xcodebuild 下的不稳定性。
// 替换：在 Package.swift 中保留 .copy("App/Resources/DemoCoverImages") 用于 macOS 测试构建，
// 但实际运行时通过本文件加载。

import Foundation
#if canImport(UIKit)
import UIKit
#endif

enum DemoCoverImageStore {
    static let android_notesPNG: String = ""
        + ""
    static let bright_moonPNG: String = ""
        + ""
    static let long_nightPNG: String = ""
        + ""
    static let mystery_lordPNG: String = ""
        + ""
    static let renjian_cihuaPNG: String = ""
        + ""
    static let three_bodyPNG: String = ""
        + ""

    /// 根据 demo-cover key 返回对应的 PNG Data。
    /// key 接受 camelCase（来自 fixture，如 "longNight"）或 kebab-case（PNG 文件名，如 "long-night"）。
    static func pngData(forCoverKey key: String) -> Data? {
        let b64: String?
        switch key {
        case "android-notes", "androidNotes": b64 = android_notesPNG
        case "bright-moon", "brightMoon": b64 = bright_moonPNG
        case "long-night", "longNight": b64 = long_nightPNG
        case "mystery-lord", "mysteryLord": b64 = mystery_lordPNG
        case "renjian-cihua", "renjian": b64 = renjian_cihuaPNG
        case "three-body", "threeBody": b64 = three_bodyPNG
        default: b64 = nil
        }
        guard let b64, let data = Data(base64Encoded: b64) else { return nil }
        return data
    }

    #if canImport(UIKit)
    static func uiImage(forCoverKey key: String) -> UIImage? {
        guard let data = pngData(forCoverKey: key) else { return nil }
        return UIImage(data: data)
    }
    #endif
}
